style.css:
@-moz-document domain("seaart.ai") {
/* Fondo principal */
  body {
    background-color: #006DB2 !important;
  }

  /* Fondos comunes */
  div, section, header, footer, aside {
    background-color: #006DB2 !important;
  }

  /* Modales, paneles, overlays */
  .modal, .popup, .drawer, .dialog,
  .overlay, .shadow, .card {
    background-color: #006DB2 !important;
  }

  /* Fondos definidos como negros en estilo inline */
  [style*="background-color: rgb(0, 0, 0)"],
  [style*="background-color: #000"],
  [style*="background-color:#000"] {
    background-color: #006DB2 !important;
  }

  /* Bordes negros → azul */
  *[style*="border-color: rgb(0, 0, 0)"],
  *[style*="border-color: #000"],
  *[style*="border-color:#000"] {
    border-color: #006DB2 !important;
  }

  /* Barras y menús comunes con fondo + borde azul */
  .sidebar,
  .menu,
  .nav,
  .panel {
    background-color: #006DB2 !important;
    border-color: #006DB2 !important;
  }

  /* Selector de modelo con transparencia azul */
  .model-selector,
  .model-dropdown,
  .select-box {
    background-color: rgba(0, 109, 178, 0.6) !important;
    backdrop-filter: blur(4px);
  }

  /* Mantener color de texto original */
  * {
    color: inherit !important;
  }
}
